from __future__ import annotations

import ast
import io
import re
import tokenize
from pathlib import Path

_SRC = Path(__file__).resolve().parents[1] / "src" / "holotrauma3x"
_FORBIDDEN = (
    "comprehensive",
    "robust",
    "state-of-the-art",
    "cutting-edge",
    "seamless",
    "leverage",
    "leveraging",
    "utilize",
    "delve",
    "holistic",
    "meticulous",
    "reproduction of",
    "re-implementation",
    "based on the paper",
    "following the authors",
    "generated by",
)
_EMOJI = re.compile(
    "[\U0001f300-\U0001faff\U00002600-\U000027bf\U0001f000-\U0001f0ff\U00002190-\U000021ff]"
)


def _sources() -> list[Path]:
    return sorted(_SRC.rglob("*.py"))


def test_no_comments() -> None:
    offenders: list[str] = []
    for path in _sources():
        with tokenize.open(path) as handle:
            for token in tokenize.generate_tokens(handle.readline):
                if token.type == tokenize.COMMENT:
                    offenders.append(f"{path.name}:{token.start[0]}")
    assert offenders == []


def test_no_docstrings() -> None:
    offenders: list[str] = []
    for path in _sources():
        tree = ast.parse(path.read_text())
        for node in ast.walk(tree):
            if isinstance(
                node, ast.Module | ast.ClassDef | ast.FunctionDef | ast.AsyncFunctionDef
            ) and ast.get_docstring(node):
                offenders.append(f"{path.name}:{getattr(node, 'name', 'module')}")
    assert offenders == []


def test_no_forbidden_phrases() -> None:
    offenders: list[str] = []
    for path in _sources():
        lowered = path.read_text().lower()
        offenders.extend(f"{path.name}:{phrase}" for phrase in _FORBIDDEN if phrase in lowered)
    assert offenders == []


def test_no_emoji() -> None:
    for path in _sources():
        assert not _EMOJI.search(path.read_text()), path.name


def test_tokenize_consistency() -> None:
    for path in _sources():
        text = path.read_text()
        list(tokenize.generate_tokens(io.StringIO(text).readline))
